-- The library used to value activities described in people's own words now
-- matches the Social Value Engine's global proxy list of 30 October 2026,
-- without the National TOMs proxies, which are licensed. Proxies no longer on
-- the list are switched off so new activities can't be valued with them;
-- saved entries keep the values they were saved with. Proxies still on it
-- take its current value and unit. The API's startup seed (proxyStore.ts)
-- adds the new ones from proxyData.json.
CREATE TEMP TABLE sve_proxies (
  title text PRIMARY KEY,
  value numeric(14, 2) NOT NULL,
  unit text NOT NULL,
  source_year text NOT NULL,
  allowed_units text[] NOT NULL
);


-- A changed unit changes which units the matcher may pair with the proxy.
UPDATE proxies p
SET value = s.value,
    unit = s.unit,
    source_year = s.source_year,
    allowed_units = CASE WHEN p.unit <> s.unit THEN s.allowed_units ELSE p.allowed_units END,
    updated_by = 'SVE proxy list, 30 Oct 2026',
    updated_at = now()
FROM sve_proxies s
WHERE p.title = s.title
  AND (p.value <> s.value OR p.unit <> s.unit OR p.source_year <> s.source_year);

UPDATE proxies
SET enabled = false,
    updated_by = 'SVE proxy list, 30 Oct 2026',
    updated_at = now()
WHERE enabled
  AND title NOT IN (SELECT title FROM sve_proxies);

DROP TABLE sve_proxies;
